The this keyword in JavaScript can behave differently depending on where and how it is used, making it one of the trickiest concepts to master. Its value is determined by the execution context and changes between strict and non-strict modes.In browsers, this refers to the global window object in the global context.In Node.js CommonJS modules, top-level this refers to module.exports ({}).Strict mode affects this inside functions, not in the global context.1. Behavior of this inside browserIn a browser, 'this' refers to the global window object in the global context or the object that owns the method being called.In this case this is pointing to it's current executional context  which is the window object2. Behavior of this inside Node.jsIn Node.js CommonJS modules, top-level this refers to module.exports, which is initially an empty object {}.
            Javascript

    //function this node.js
console.log(this)

Output{}
3. Inside a function kept in global spaceInside a function in the global space, this refers to the global object (window in browsers, global in Node.js) in non-strict mode, but is undefined` in strict mode.In Strict Mode
            Javacript

    //function strict.js

"use strict";
function a() {
	console.log(this); 
}
a();

Outputundefined
In Normal Mode
            JavaScript

    // non strict mode

function a(){
	console.log(this); 
}
a();

Output<ref *1> Object [global] {
  global: [Circular *1],
  clearInterval: [Function: clearInterval],
  clearTimeout: [Function: clearTimeout],
  setInterval: [Function: setInterval],
  setTimeout: [Functio...4. In arrow functions kept in global spaceIn arrow functions, this is automatically inherited from the surrounding context or the parent context. It has same behavior in strict and non strict mode.
            Javascript

    "use strict";
let a = () => { 
	console.log(this) 
} 

a();

Output{}
5. In anonymous functions kept in global spaceIn anonymous functions 'this' refers to the global object in non strict mode and undefined in strict mode.In Strict Mode
            JavaScript

    "use strict";
let a = function() { console.log(this); } a();

Outputundefined
In Normal Mode
            JavaScript

    //non strict mode

let a = function () { 
    console.log(this); 
}

a();

Output<ref *1> Object [global] {
  global: [Circular *1],
  clearInterval: [Function: clearInterval],
  clearTimeout: [Function: clearTimeout],
  setInterval: [Function: setInterval],
  setTimeout: [Functio...6. Inside a normal function kept in an objectThe 'this' inside a function which is kept inside any object always points to that object because this refers to the object from which the method is called.
            JavsaScript

    let obj = {a : 10, b : function() { 
    console.log(this); 
}} 

obj.b();

7. Inside an arrow function in an objectInside an arrow function in an object, this does not refer to the object but inherits this from the surrounding context where the function is defined.
            JavaScript

    let obj = {a : 10, b : () => {
    console.log(this); 
}}

obj.b();

Output{}
8. Inside an arrow function kept inside a normal functionInside an arrow function within a normal function in an object, this still inherits from the surrounding context, not the object itself.
            Javacript

    let obj = {
    name : "Pranjal",
    a : function() {
        let b = () => { 
            console.log(this.name); 
        } 
        b();
    }
} 
obj.a();

9. Inside nested arrow functions in an object In a nested arrow function, this is inherited from the outer function where the arrow function is defined. It does not change based on the inner function's context.
            JavaScript

    let obj = {
    name: "Pranjal",
    a: () => {
        let b = () => {
            console.log(this);
        };
        b();
    },
};
obj.a();

Output{}
10. Inside nested normal functions in an objectInside nested normal functions in an object, 'this' points to the global object because regular functions have their own this. Therefore, the nested function's this is determined by how it is called and does not automatically inherit the parent's this.
            Javascript

    let obj = {
    name: "Pranjal",
    a: function () {
        let b = function () {
            console.log(this);
        };
        b();
    },
};
obj.a();

Output<ref *1> Object [global] {
  global: [Circular *1],
  clearInterval: [Function: clearInterval],
  clearTimeout: [Function: clearTimeout],
  setInterval: [Function: setInterval],
  setTimeout: [Functio...11. Behavior of 'this' in callIn call(), this is set to the object reference you pass as the first argument, allowing the function to use that object's properties.
            JavaScript

    let obj = {
    name: "GEEKS FOR GEEKS",
};
function print(greet) {
    console.log(`${greet} Welcome to ${this.name}`);
}
print.call(obj, "Hello");

12. Behavior of 'this' in ApplyIn apply(), 'this' is set to the first argument (an object), and the second argument is an array of values for the function. In apply() we have to pass arguments to the function as a list.      
            JavaScript

    let obj = {
    name: "GEEKS FOR GEEKS"
}
function print(greet) {
    console.log(`${greet} Welcome to ${this.name}`);
}
print.apply(obj, ["Hello"]);

13. Behavior of this in bind In bind(), this is set to the object you pass, and it returns a new function that you must call to use the bound 'this'.
            JavaScript

    let obj = {
    name: "GEEKS FOR GEEKS"
}
function print(greet) {
    console.log(`${greet} Welcome to ${this.name}`);
}
let result = print.bind(obj, "Hello");
result();

14. Behavior of this inside DOM elementInside the DOM element the this point to the current element in which it is placed
